/**
 * Chart：折线、柱状、面积、环形四种图，一个入口、一套属性。基于 TanStack Charts（MIT，https://tanstack.com/charts）。
 * 颜色只用令牌：系列取 --chart-1 到 --chart-5（品牌层，跟随暗色），坐标轴、网格、文字取语义令牌。
 * 动效：motion="grow"（缺省）用 TanStack Charts 的 motion 渲染器进场，时长读 --motion-grow-duration，
 * 曲线读 --motion-ease-enter；motion="none" 或 reduced-motion 时用静态 SVG 渲染器，直接画终值。
 * 纯逻辑在 chart-model.ts。
 */
import { areaY, barY, defineChart, group, lineY } from "@tanstack/charts";
import { crosshair } from "@tanstack/charts/crosshair";
import { motion as motionRenderer } from "@tanstack/charts/motion";
import { pie, polar, radialArc } from "@tanstack/charts/polar";
import { RendererChart } from "@tanstack/charts/react/tooltip";
import { scaleBand } from "@tanstack/charts/scales/band";
import { scaleLinear } from "@tanstack/charts/scales/linear";
import { scalePoint } from "@tanstack/charts/scales/point";
import { svgChartRenderer } from "@tanstack/charts/svg/renderer";
import { type ChartTooltipContent, tooltip } from "@tanstack/charts/tooltip";
import { cn } from "cn";
import {
  type CSSProperties,
  type ReactNode,
  type RefObject,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  useSyncExternalStore,
} from "react";

import {
  type ChartMotion,
  type ChartSeries,
  type ChartType,
  type DonutSlice,
  donutSlices,
  growTransition,
  hasData,
  type LongRow,
  limitSeries,
  parsePixels,
  type ResolvedSeries,
  seriesColor,
  toLongRows,
} from "@/components/ui/chart-model";
import { Empty, EmptyDescription, EmptyHeader, EmptyTitle } from "@/components/ui/empty";
import { Skeleton } from "@/components/ui/skeleton";
import { formatNumber } from "@/lib/format";

const REDUCED_QUERY = "(prefers-reduced-motion: reduce)";

function subscribeReduced(onChange: () => void): () => void {
  if (typeof window === "undefined" || typeof window.matchMedia !== "function") return () => {};
  const query = window.matchMedia(REDUCED_QUERY);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
}

/** 系统是否要求减弱动态效果（prefers-reduced-motion）；跟着系统设置实时变。 */
function useReducedMotion(): boolean {
  return useSyncExternalStore(
    subscribeReduced,
    () => typeof window.matchMedia === "function" && window.matchMedia(REDUCED_QUERY).matches,
    () => false,
  );
}

/** 从根元素读到的令牌：动效预设的时长与曲线、发丝线宽度。SSR 与首帧用缺省值。 */
type ChartTokens = { duration: string | null; ease: string | null; hairline: number };

const DEFAULT_TOKENS: ChartTokens = { duration: null, ease: null, hairline: 1 };

function useChartTokens(ref: RefObject<HTMLElement | null>): ChartTokens {
  const [tokens, setTokens] = useState(DEFAULT_TOKENS);
  useLayoutEffect(() => {
    const element = ref.current;
    if (!element) return;
    const style = getComputedStyle(element);
    const next: ChartTokens = {
      duration: style.getPropertyValue("--motion-grow-duration").trim() || null,
      ease: style.getPropertyValue("--motion-ease-enter").trim() || null,
      hairline: parsePixels(style.getPropertyValue("--hairline")) ?? 1,
    };
    setTokens((current) =>
      current.duration === next.duration &&
      current.ease === next.ease &&
      current.hairline === next.hairline
        ? current
        : next,
    );
  }, [ref]);
  return tokens;
}

/** 坐标轴文字与控件同为 12px（text-xs）。SVG 的字号要给数字，所以写在这里。 */
const TICK_FONT_SIZE = 12;

/**
 * 图表内部的主题：前景、次要文字、网格都取语义令牌；色板取 --chart-1 到 --chart-5。
 * 提示框外壳透明，外观由 ChartTooltipBody 用 Popover 的类名画（直角、bg-popover、细边、shadow-md）。
 */
const THEME = {
  foreground: "var(--foreground)",
  muted: "var(--muted-foreground)",
  grid: "var(--border)",
  background: "transparent",
  palette: [0, 1, 2, 3, 4].map(seriesColor),
};

const HOST_STYLE = {
  "--ts-chart-focus-fill": "var(--background)",
  "--ts-chart-tooltip-background": "transparent",
  "--ts-chart-tooltip-color": "var(--popover-foreground)",
  "--ts-chart-tooltip-border": "none",
  "--ts-chart-tooltip-border-radius": "0",
  "--ts-chart-tooltip-shadow": "none",
  "--ts-chart-tooltip-padding": "0",
  "--ts-chart-tooltip-font": "inherit",
} as CSSProperties;

type Formatter = (value: number | null) => string;

/** 提示框的内容：标题是 x 值（环形图是分片名），每个系列一行，带色块。 */
function cartesianContent(
  points: readonly { datum: LongRow }[],
  format: Formatter,
): ChartTooltipContent {
  return {
    title: points[0]?.datum.x ?? "",
    rows: points.map(({ datum }) => ({
      label: datum.series,
      value: format(datum.value),
      color: seriesColor(datum.index),
    })),
  };
}

function cartesianDefinition({
  type,
  rows,
  series,
  stacked,
  format,
  hairline,
}: {
  type: Exclude<ChartType, "donut">;
  rows: LongRow[];
  series: ResolvedSeries[];
  stacked: boolean;
  format: Formatter;
  hairline: number;
}) {
  const shared = { x: "x", color: "series", z: "series", key: "id" } as const;
  const line = { stroke: "var(--border)", strokeOpacity: 1, strokeWidth: hairline };
  // 焦点指示：柱状图在焦点分类下垫一条浅色底（不画圆点）；折线、面积画一条竖向细线。
  // 指示跟手，不走 grow 的过渡（motion: false）。
  const cursor =
    type === "bar"
      ? crosshair({
          x: { band: { fill: "var(--muted-foreground)", fillOpacity: 0.12 } },
          y: false,
          motion: false,
        })
      : crosshair({ x: line, y: false, motion: false });
  const data =
    type === "bar"
      ? [
          barY(rows, {
            ...shared,
            y: "value",
            ...(stacked ? {} : { layout: group({ padding: 0.08 }) }),
          }),
        ]
      : type === "line"
        ? [lineY(rows, { ...shared, y: "value", strokeWidth: 1.5 })]
        : stacked
          ? [areaY(rows, { ...shared, y: "value", fillOpacity: 0.5 })]
          : [
              areaY(rows, { ...shared, y1: 0, y2: "value", fillOpacity: 0.16 }),
              lineY(rows, { ...shared, y: "value", strokeWidth: 1.5 }),
            ];
  const marks = [cursor, ...data];
  return defineChart({
    marks,
    scales: {
      x: {
        scale: type === "bar" ? () => scaleBand<string>().padding(0.2) : () => scalePoint<string>(),
        axis: {
          line,
          ticks: { size: 0, padding: 8 },
          tickLabels: { fontSize: TICK_FONT_SIZE, opacity: 1 },
        },
      },
      y: {
        scale: scaleLinear,
        nice: true,
        grid: line,
        axis: {
          line: false,
          ticks: { size: 0, padding: 8, format: (value: number) => format(value) },
          tickLabels: { fontSize: TICK_FONT_SIZE, opacity: 1 },
        },
      },
    },
    color: {
      domain: series.map((item) => item.label),
      range: series.map((_, index) => seriesColor(index)),
    },
    theme: THEME,
    // 不要库自带的入场错峰：整张图一起生长，总时长就是预设的 600ms。
    motion: { delay: 0 },
    focus: "group-x",
    focusRing: type !== "bar",
    tooltip: {
      use: tooltip,
      motion: false,
      content: (points) => cartesianContent(points, format),
    },
  });
}

function donutDefinition({ slices, format }: { slices: DonutSlice[]; format: Formatter }) {
  const total = slices.reduce((sum, slice) => sum + slice.value, 0);
  const share = (value: number) =>
    total > 0 ? formatNumber(value / total, { style: "percent", maximumFractionDigits: 1 }) : "";
  return defineChart({
    marks: [
      polar({
        radiusRatio: 0.9,
        marks: [
          radialArc(pie(slices, { value: "value", gapAngle: 0.012 }), {
            innerRadius: ({ radius }) => radius * 0.62,
            color: "label",
            key: "id",
            // 焦点不画圆点：其余分片变淡，焦点分片保持原色。
            states: [{ when: { focus: "unmatched" }, style: { opacity: 0.35 } }],
          }),
        ],
        scales: { angle: null, radius: null },
      }),
    ],
    scales: { x: null, y: null },
    focusRing: false,
    color: {
      domain: slices.map((slice) => slice.label),
      range: slices.map((slice) => slice.color),
    },
    theme: THEME,
    // 不要库自带的入场错峰：整张图一起生长，总时长就是预设的 600ms。
    motion: { delay: 0 },
    tooltip: {
      use: tooltip,
      motion: false,
      content: (points) => ({
        rows: points.map(({ datum }) => ({
          label: datum.label,
          value: `${format(datum.value)}（${share(datum.value)}）`,
          color: datum.color,
        })),
      }),
    },
  });
}

/** 提示框的外观与 Popover 一致：直角、bg-popover、细边、shadow-md、text-xs。 */
function ChartTooltipBody({ content }: { content: ChartTooltipContent | string }) {
  if (typeof content === "string") {
    return <div className={TOOLTIP_CLASS}>{content}</div>;
  }
  return (
    <div className={TOOLTIP_CLASS}>
      {content.title ? <div className="font-medium">{content.title}</div> : null}
      <dl className="flex flex-col gap-1">
        {content.rows.map((row) => (
          <div key={row.label} className="flex items-center gap-2">
            <span
              aria-hidden="true"
              className="size-2 shrink-0"
              style={{ background: row.color }}
            />
            <dt className="text-muted-foreground">{row.label}</dt>
            <dd className="ml-auto pl-3 font-medium tabular-nums">{row.value}</dd>
          </div>
        ))}
      </dl>
    </div>
  );
}

const TOOLTIP_CLASS =
  "flex min-w-32 flex-col gap-1.5 rounded-surface bg-popover p-2.5 text-xs text-popover-foreground shadow-md ring-1 ring-foreground/10";

/** 图例：色块加名字，一行排不下就换行。 */
function ChartLegend({ items }: { items: readonly { label: string; color: string }[] }) {
  return (
    <ul data-slot="chart-legend" className="flex flex-wrap gap-x-3 gap-y-1 text-muted-foreground">
      {items.map((item) => (
        <li key={item.label} className="flex items-center gap-1.5">
          <span aria-hidden="true" className="size-2 shrink-0" style={{ background: item.color }} />
          {item.label}
        </li>
      ))}
    </ul>
  );
}

/** 读屏用的数据表：视觉上隐藏，给出图上每个精确值。 */
function ChartDataTable({
  caption,
  head,
  rows,
}: {
  caption: string;
  head: readonly string[];
  rows: readonly (readonly string[])[];
}) {
  return (
    <table data-slot="chart-table" className="sr-only">
      <caption>{caption}</caption>
      <thead>
        <tr>
          {head.map((cell) => (
            <th key={cell} scope="col">
              {cell}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((row) => (
          <tr key={row[0]}>
            <th scope="row">{row[0]}</th>
            {row.slice(1).map((cell, index) => (
              // 同一行的单元格只按列序区分。
              // biome-ignore lint/suspicious/noArrayIndexKey: 列序就是身份
              <td key={index}>{cell}</td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

/** 数据行里值为数字（可缺）的字段名。 */
type NumericKey<Row> = {
  [Key in keyof Row]: Row[Key] extends number | null | undefined ? Key : never;
}[keyof Row] &
  string;

type ChartProps<Row extends Record<string, unknown>> = {
  /** 图表类型：`line` 趋势、`bar` 分类比较、`area` 累计量、`donut` 占比。 */
  type: ChartType;
  /** 数据：每行一个 x 值（环形图每行一片）。传模块常量、state 或 useMemo 的结果。 */
  data: readonly Row[];
  /** 横轴（环形图是分片名）取哪个字段。值按字符串显示，日期先格式化。 */
  x: Extract<keyof Row, string>;
  /** 要画的数值字段，最多 5 个，按顺序取 --chart-1 到 --chart-5。环形图只用第一个。 */
  series: readonly ChartSeries<NumericKey<Row>>[];
  /** 图表的名字，读屏读它，也是数据表的标题。 */
  "aria-label": string;
  /** 补充说明（单位、时间范围），读屏在名字之后读。 */
  description?: string;
  /** 高度（px），缺省 240。宽度跟随容器。 */
  height?: number;
  /** 柱状、面积图把多个系列叠起来。缺省 false：柱状并排，面积重叠。 */
  stacked?: boolean;
  /** 数值格式，原样传给 formatNumber（坐标轴、提示框、数据表）。 */
  valueFormat?: Intl.NumberFormatOptions;
  /** 显示图例。缺省：多系列与环形图显示。 */
  legend?: boolean;
  /** 加载中：显示同高的骨架。 */
  loading?: boolean;
  /** 空态标题，缺省「暂无数据」。 */
  emptyTitle?: string;
  /** 空态说明。 */
  emptyDescription?: ReactNode;
  /**
   * 动效预设（ADR 0021）。缺省 `grow`。
   * - `grow`：首次绘制时生长进场（柱从基线升起、线从基线展开、环形扫开），600ms ease-enter。
   * - `none`：直接画终值。
   */
  motion?: ChartMotion;
  className?: string;
};

const DEFAULT_HEIGHT = 240;

function Chart<Row extends Record<string, unknown>>({
  type,
  data,
  x,
  series,
  "aria-label": ariaLabel,
  description,
  height = DEFAULT_HEIGHT,
  stacked = false,
  valueFormat,
  legend,
  loading = false,
  emptyTitle = "暂无数据",
  emptyDescription,
  motion = "grow",
  className,
}: ChartProps<Row>) {
  const ref = useRef<HTMLDivElement>(null);
  const reduced = useReducedMotion();
  const tokens = useChartTokens(ref);
  // 系列与数值格式常写成行内字面量：按内容比较，免得每次渲染都重建图表。
  const seriesKey = JSON.stringify(series);
  const resolved = useMemo(
    () => limitSeries(JSON.parse(seriesKey) as readonly ChartSeries[]),
    [seriesKey],
  );
  const formatKey = JSON.stringify(valueFormat ?? null);
  const format = useMemo<Formatter>(() => {
    const options = (JSON.parse(formatKey) as Intl.NumberFormatOptions | null) ?? undefined;
    return (value) => formatNumber(value, options);
  }, [formatKey]);
  const rows = data as readonly Record<string, unknown>[];
  const slices = useMemo(
    () => (type === "donut" && resolved[0] ? donutSlices(rows, x, resolved[0].key) : []),
    [type, rows, x, resolved],
  );
  const longRows = useMemo(() => toLongRows(rows, x, resolved), [rows, x, resolved]);

  const definition = useMemo(
    () =>
      type === "donut"
        ? donutDefinition({ slices, format })
        : cartesianDefinition({
            type,
            rows: longRows,
            series: resolved,
            stacked,
            format,
            hairline: tokens.hairline,
          }),
    [type, slices, longRows, resolved, stacked, format, tokens.hairline],
  );

  const transition = useMemo(
    () => growTransition({ motion, reduced, cssDuration: tokens.duration, cssEase: tokens.ease }),
    [motion, reduced, tokens.duration, tokens.ease],
  );
  const transitionKey = transition?.id ?? "static";
  const renderer = useMemo(
    () =>
      transition
        ? motionRenderer({ transition, initial: "always", respectReducedMotion: true })
        : svgChartRenderer,
    [transition],
  );

  const legendItems =
    type === "donut"
      ? slices.map((slice) => ({ label: slice.label, color: slice.color }))
      : resolved.map((item, index) => ({ label: item.label, color: seriesColor(index) }));
  const showLegend = legend ?? (type === "donut" || resolved.length > 1);

  const empty = !hasData(rows, resolved.slice(0, type === "donut" ? 1 : undefined));
  let body: ReactNode;
  if (loading) {
    body = <Skeleton data-slot="chart-skeleton" className="w-full" style={{ height }} />;
  } else if (empty) {
    body = (
      <Empty data-slot="chart-empty" className="border border-border" style={{ minHeight: height }}>
        <EmptyHeader>
          <EmptyTitle>{emptyTitle}</EmptyTitle>
          {emptyDescription ? <EmptyDescription>{emptyDescription}</EmptyDescription> : null}
        </EmptyHeader>
      </Empty>
    );
  } else {
    const table =
      type === "donut"
        ? {
            head: [x, resolved[0]?.label ?? ""],
            rows: slices.map((slice) => [slice.label, format(slice.value)]),
          }
        : {
            head: [x, ...resolved.map((item) => item.label)],
            rows: rows.map((row) => [
              String(row[x]),
              ...resolved.map((item) => {
                const value = row[item.key];
                return format(typeof value === "number" ? value : null);
              }),
            ]),
          };
    body = (
      <>
        {showLegend ? <ChartLegend items={legendItems} /> : null}
        <RendererChart
          key={transitionKey}
          definition={definition as Parameters<typeof RendererChart>[0]["definition"]}
          renderer={renderer as Parameters<typeof RendererChart>[0]["renderer"]}
          ariaLabel={ariaLabel}
          {...(description ? { ariaDescription: description } : {})}
          height={height}
          className="outline-none [&_svg:focus-visible]:outline-1 [&_svg:focus-visible]:outline-ring"
          style={HOST_STYLE}
          renderTooltipBody={({ content }) => <ChartTooltipBody content={content} />}
        />
        <ChartDataTable caption={ariaLabel} head={table.head} rows={table.rows} />
      </>
    );
  }

  return (
    <div
      ref={ref}
      data-slot="chart"
      data-type={type}
      data-motion={motion}
      aria-busy={loading || undefined}
      className={cn("flex w-full min-w-0 flex-col gap-3 text-xs text-foreground", className)}
    >
      {body}
    </div>
  );
}

export { Chart, type ChartMotion, type ChartProps, type ChartSeries, type ChartType };

/**
 * Chart 的纯逻辑：系列颜色、宽表转长表、环形图分片、空数据判断，以及 grow 预设的时长与曲线。
 * 不依赖 React、DOM 与 TanStack Charts，`node --test` 直接测（chart-model.test.mjs）。
 */

/** 图表类型。 */
export type ChartType = "line" | "bar" | "area" | "donut";

/** Chart 支持的动效预设（ADR 0021）。缺省 `grow`。 */
export type ChartMotion = "grow" | "none";

/** 一个数据系列：`key` 是数据行里的数值字段，`label` 是图例、提示框与表格里显示的名字。 */
export type ChartSeries<Key extends string = string> = {
  key: Key;
  label?: string;
};

/** 补齐 label 之后的系列。 */
export type ResolvedSeries = { key: string; label: string };

/** 系列颜色只有 --chart-1 到 --chart-5 五个（品牌层）。 */
export const MAX_SERIES = 5;

/** 第 index 个系列（或环形图的第 index 片）的颜色：按顺序取 --chart-1 到 --chart-5。 */
export function seriesColor(index: number): string {
  return `var(--chart-${(index % MAX_SERIES) + 1})`;
}

/** 只保留前 5 个系列，并补齐 label（没写时用 key）。 */
export function limitSeries(series: readonly ChartSeries[]): ResolvedSeries[] {
  return series
    .slice(0, MAX_SERIES)
    .map((item) => ({ key: item.key, label: item.label ?? item.key }));
}

/** 有限数原样返回，其它（null、字符串、NaN）返回 null：图上断开，不画成 0。 */
function finiteOrNull(value: unknown): number | null {
  return typeof value === "number" && Number.isFinite(value) ? value : null;
}

/** 长表的一行：一个 x 值上一个系列的值。 */
export type LongRow = {
  /** 稳定的标识：`<x>:<系列 key>`，动效与焦点按它对应。 */
  id: string;
  x: string;
  /** 系列的 label，颜色比例尺与提示框按它分组。 */
  series: string;
  /** 系列序号，决定颜色。 */
  index: number;
  value: number | null;
};

/** 宽表（每行一个 x 值、每个系列一列）转成长表（每行一个 x 值上的一个系列）。 */
export function toLongRows(
  data: readonly Record<string, unknown>[],
  x: string,
  series: readonly ResolvedSeries[],
): LongRow[] {
  return data.flatMap((row) =>
    series.map((item, index) => {
      const xValue = String(row[x]);
      return {
        id: `${xValue}:${item.key}`,
        x: xValue,
        series: item.label,
        index,
        value: finiteOrNull(row[item.key]),
      };
    }),
  );
}

/** 至少有一个有限数值时才有可画的数据；0 也算。 */
export function hasData(
  data: readonly Record<string, unknown>[],
  series: readonly ChartSeries[],
): boolean {
  return data.some((row) => series.some((item) => finiteOrNull(row[item.key]) !== null));
}

/** 环形图的一片。 */
export type DonutSlice = { id: string; label: string; value: number; color: string };

/** 超过 5 项时并出来的那一片的名字。 */
export const OTHER_LABEL = "其他";

/**
 * 环形图的分片：去掉缺值与负数；不超过 5 项时原样保留顺序；
 * 超过 5 项时保留最大的 4 项（原顺序），其余并成「其他」，颜色仍只有五个。
 */
export function donutSlices(
  data: readonly Record<string, unknown>[],
  label: string,
  value: string,
): DonutSlice[] {
  const valid = data.flatMap((row) => {
    const amount = finiteOrNull(row[value]);
    return amount === null || amount < 0 ? [] : [{ label: String(row[label]), value: amount }];
  });
  let kept = valid;
  if (valid.length > MAX_SERIES) {
    const largest = new Set(
      [...valid].sort((left, right) => right.value - left.value).slice(0, MAX_SERIES - 1),
    );
    const rest = valid.filter((slice) => !largest.has(slice));
    kept = [
      ...valid.filter((slice) => largest.has(slice)),
      { label: OTHER_LABEL, value: rest.reduce((sum, slice) => sum + slice.value, 0) },
    ];
  }
  return kept.map((slice, index) => ({
    id: slice.label,
    label: slice.label,
    value: slice.value,
    color: seriesColor(index),
  }));
}

/** grow 的缺省时长（毫秒）。与 base.css 的 --motion-grow-duration 一致；读不到该变量时用它。 */
export const GROW_DURATION = 600;

/** ease-enter 的缺省控制点，与 base.css 的 --motion-ease-enter 一致。 */
const EASE_ENTER: readonly [number, number, number, number] = [0.23, 1, 0.32, 1];

/** CSS 时长文本 → 毫秒：`600ms` → 600，`0.6s` → 600；读不懂返回 null。 */
export function parseDuration(text: string | null | undefined): number | null {
  const match = /^\s*(-?[\d.]+)(ms|s)\s*$/.exec(text ?? "");
  if (!match) return null;
  const value = Number(match[1]) * (match[2] === "s" ? 1000 : 1);
  return Number.isFinite(value) && value >= 0 ? value : null;
}

/** CSS 长度文本 → 像素：`1px` → 1；读不懂返回 null。用来把 --hairline 交给 SVG 的线宽。 */
export function parsePixels(text: string | null | undefined): number | null {
  const match = /^\s*([\d.]+)px\s*$/.exec(text ?? "");
  if (!match) return null;
  const value = Number(match[1]);
  return Number.isFinite(value) ? value : null;
}

/** `cubic-bezier(x1, y1, x2, y2)` → 四个数；不是合法的 cubic-bezier 时返回 null。 */
export function parseCubicBezier(
  text: string | null | undefined,
): [number, number, number, number] | null {
  const match = /^\s*cubic-bezier\(([^)]*)\)\s*$/.exec(text ?? "");
  if (!match?.[1]) return null;
  const numbers = match[1].split(",").map((part) => Number(part.trim()));
  if (numbers.length !== 4 || numbers.some((number) => !Number.isFinite(number))) return null;
  const [x1, y1, x2, y2] = numbers as [number, number, number, number];
  if (x1 < 0 || x1 > 1 || x2 < 0 || x2 > 1) return null;
  return [x1, y1, x2, y2];
}

/** CSS 的 cubic-bezier 缓动：先由时间进度 x 解出参数 t（牛顿法，不收敛时二分），再取 y。 */
export function cubicBezier(x1: number, y1: number, x2: number, y2: number) {
  const cx = 3 * x1;
  const bx = 3 * (x2 - x1) - cx;
  const ax = 1 - cx - bx;
  const cy = 3 * y1;
  const by = 3 * (y2 - y1) - cy;
  const ay = 1 - cy - by;
  const sampleX = (t: number) => ((ax * t + bx) * t + cx) * t;
  const sampleY = (t: number) => ((ay * t + by) * t + cy) * t;
  const slopeX = (t: number) => (3 * ax * t + 2 * bx) * t + cx;

  const solve = (x: number) => {
    let t = x;
    for (let step = 0; step < 8; step += 1) {
      const error = sampleX(t) - x;
      if (Math.abs(error) < 1e-6) return t;
      const slope = slopeX(t);
      if (Math.abs(slope) < 1e-6) break;
      t -= error / slope;
    }
    let low = 0;
    let high = 1;
    t = x;
    while (high - low > 1e-6) {
      if (sampleX(t) < x) low = t;
      else high = t;
      t = (low + high) / 2;
    }
    return t;
  };

  return (progress: number): number => {
    if (progress <= 0) return 0;
    if (progress >= 1) return 1;
    return sampleY(solve(progress));
  };
}

/** grow 的过渡：交给 TanStack Charts 的 motion 渲染器。 */
export type GrowTransition = {
  /** 时长加曲线的文本，渲染器按它缓存：值不变就不重建。 */
  id: string;
  type: "tween";
  duration: number;
  easing: (progress: number) => number;
};

/**
 * 这次进场要怎么动；null 表示不动，直接画终值（用静态 SVG 渲染器）。
 * motion 为 none、要求减弱动态效果、时长不为正，都返回 null。
 * 时长取 --motion-grow-duration，曲线取 --motion-ease-enter；读不到时用缺省值。
 */
export function growTransition({
  motion,
  reduced,
  cssDuration,
  cssEase,
}: {
  motion: ChartMotion;
  reduced: boolean;
  cssDuration?: string | null | undefined;
  cssEase?: string | null | undefined;
}): GrowTransition | null {
  if (motion !== "grow" || reduced) return null;
  const duration = parseDuration(cssDuration) ?? GROW_DURATION;
  if (duration <= 0) return null;
  const points = parseCubicBezier(cssEase) ?? EASE_ENTER;
  return {
    id: `${duration}ms:${points.join(",")}`,
    type: "tween",
    duration,
    easing: cubicBezier(...points),
  };
}
